import{_ as a,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"控制台特性｜实现丰富的命令行交互体验","description":"","frontmatter":{},"headers":[{"level":2,"title":"基础：问答式IO","slug":"基础-问答式io","link":"#基础-问答式io","children":[]},{"level":2,"title":"实时响应IO","slug":"实时响应io","link":"#实时响应io","children":[]},{"level":2,"title":"命令行指令","slug":"命令行指令","link":"#命令行指令","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"重学前端/控制台特性｜实现丰富的命令行交互体验.md","filePath":"重学前端/控制台特性｜实现丰富的命令行交互体验.md","lastUpdated":1779822672000}'),i={name:"重学前端/控制台特性｜实现丰富的命令行交互体验.md"};function l(t,s,o,c,r,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="控制台特性-实现丰富的命令行交互体验" tabindex="-1">控制台特性｜实现丰富的命令行交互体验 <a class="header-anchor" href="#控制台特性-实现丰富的命令行交互体验" aria-label="Permalink to &quot;控制台特性｜实现丰富的命令行交互体验&quot;">​</a></h1><p>你好，我是 winter。</p><p>在 Node.js 工具开发中，控制台（Console）是一个至关重要的组件。它不仅是我们与用户交互的主要界面，更是调试和监控应用程序状态的关键工具。</p><p>通过合理使用控制台，我们可以提供清晰的命令行界面（CLI），实现优雅的错误处理和提示，展示进度和状态信息，支持调试和日志记录，以及实现交互式的用户输入。</p><p>掌握控制台的使用，对于开发高质量的 Node.js 工具来说是不可或缺的技能。</p><p>在本节课中，我们将会以逐步深入的方式学习命令行界面的技术。</p><p>首先从最基础的问答式 IO 模式命令行交互开始，接下来学习切换到实时响应模式，然后学习通过命令行指令来丰富表现能力，最后，我们会通过学习一些 Unicode 字符，实现在命令行中添加简单的图形能力。</p><h2 id="基础-问答式io" tabindex="-1">基础：问答式IO <a class="header-anchor" href="#基础-问答式io" aria-label="Permalink to &quot;基础：问答式IO&quot;">​</a></h2><p>在 Node.js 中，标准输入输出（stdin/stdout）是最基础的 IO 接口。通过 <code>process.stdin</code> 和 <code>process.stdout</code>，我们可以实现最基本的命令行交互。标准输入用于接收用户输入，标准输出用于向用户展示信息。 <strong>这种基础的 IO 模式虽然简单，但却是所有高级交互模式的基础。</strong></p><p>前面课程中已经介绍过， <code>process.stdin</code> 是一个流（Stream），在命令行作为标准输入时，它只有在用户按下回车键后才会触发 <code>data</code> 事件，此时程序才能读取到用户输入的内容。这意味着：</p><ol><li>程序无法实时获取用户正在输入的内容。</li><li>每次读取都会包含用户输入的所有内容，包括回车符。</li><li>如果用户没有输入任何内容就按回车，会得到一个空字符串。</li></ol><p>这种特性使得标准输入更适合处理完整的命令或回答，而不是实时的交互场景。</p><h2 id="实时响应io" tabindex="-1">实时响应IO <a class="header-anchor" href="#实时响应io" aria-label="Permalink to &quot;实时响应IO&quot;">​</a></h2><p>我们可以通过调用 <code>process.stdin.setRawMode(true)</code> 将标准输入切换到 raw 模式。在 raw 模式下：</p><ol><li>程序可以立即接收到每个按键的输入，不需要等待回车。</li><li>输入内容不会经过终端的预处理，直接以原始形式传递给程序。</li><li>特殊按键（如方向键、Ctrl+C 等）会以特殊的字符序列形式传递。</li></ol><p>这种模式特别适合开发需要实时响应用户按键的工具，比如命令行游戏、终端编辑器等。 <strong>但需要注意的是，在 raw 模式下，我们需要自己处理特殊按键（如 Ctrl+C），否则程序可能无法正常退出。</strong></p><p>下面是一个简单的示例，展示了如何使用 raw 模式来实时响应按键：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>process.stdin.setRawMode(true);</span></span>
<span class="line"><span>process.stdin.resume();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 监听按键输入</span></span>
<span class="line"><span>process.stdin.on(&#39;data&#39;, (key) =&amp;gt; {</span></span>
<span class="line"><span>    // Ctrl+C 的 ASCII 码是 3</span></span>
<span class="line"><span>    if (key[0] === 3) {</span></span>
<span class="line"><span>        process.exit();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 方向键的字符序列</span></span>
<span class="line"><span>    if (key[0] === 27 &amp;&amp; key[1] === 91) {</span></span>
<span class="line"><span>        switch (key[2]) {</span></span>
<span class="line"><span>            case 65: // 上箭头</span></span>
<span class="line"><span>                console.log(&#39;向上移动&#39;);</span></span>
<span class="line"><span>                break;</span></span>
<span class="line"><span>            case 66: // 下箭头</span></span>
<span class="line"><span>                console.log(&#39;向下移动&#39;);</span></span>
<span class="line"><span>                break;</span></span>
<span class="line"><span>            case 67: // 右箭头</span></span>
<span class="line"><span>                console.log(&#39;向右移动&#39;);</span></span>
<span class="line"><span>                break;</span></span>
<span class="line"><span>            case 68: // 左箭头</span></span>
<span class="line"><span>                console.log(&#39;向左移动&#39;);</span></span>
<span class="line"><span>                break;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        // 普通按键</span></span>
<span class="line"><span>        console.log(\`按下按键: \${key}\`);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>在 raw 模式下，不同的按键会产生不同的字符序列。以下是常用按键的键值对应表：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/e51a2c1ebebf70561743a1ece830b556.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/e51a2c1ebebf70561743a1ece830b556.png" alt=""></a></p><h2 id="命令行指令" tabindex="-1">命令行指令 <a class="header-anchor" href="#命令行指令" aria-label="Permalink to &quot;命令行指令&quot;">​</a></h2><p>在 Node.js 中，我们可以通过 ANSI 转义序列（ANSI Escape Sequences）来改变命令行环境。ANSI 转义序列是一种标准化的控制字符序列，用于控制终端显示效果，包括文本样式、颜色、光标位置等。这些序列以 <code>\\x1b[</code>（ESC [）开头，后面跟着不同的参数。</p><p>ANSI 转义序列最初由美国国家标准协会（ANSI）制定，现在已经成为终端显示控制的事实标准。在 ECMA-48（ISO/IEC 6429）标准中，这些序列被正式定义为“控制序列引入符”（Control Sequence Introducer，CSI），并详细规定了各种控制序列的格式和功能。</p><p>大多数现代终端都支持这些序列，包括：</p><ul><li>文本样式控制（加粗、下划线、闪烁等）</li><li>文本颜色和背景颜色</li><li>光标移动和定位</li><li>屏幕清除和滚动</li><li>其他终端控制功能</li></ul><p>在 ECMA 标准中，CSI 序列的基本格式为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CSI [参数...] [中间字符...] 最终字符</span></span></code></pre></div><p>其中：</p><ul><li>CSI 是控制序列引入符（ <code>\\x1b[</code>）</li><li>参数是可选的分号分隔的数字</li><li>中间字符是可选的 ASCII 字符</li><li>最终字符是必需的 ASCII 字符</li></ul><h4 id="文本样式和颜色" tabindex="-1">文本样式和颜色 <a class="header-anchor" href="#文本样式和颜色" aria-label="Permalink to &quot;文本样式和颜色&quot;">​</a></h4><p>以下是常用的文本样式、颜色和光标控制指令：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/e6d6e1df0fb79cf2c6afd973e6431d1b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/e6d6e1df0fb79cf2c6afd973e6431d1b.png" alt=""></a></p><p>文本样式和颜色指令的使用示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 将文本设置为红色加粗</span></span>
<span class="line"><span>console.log(&#39;\\x1b[31m\\x1b[1m红色加粗文本\\x1b[0m&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 设置红色背景上的白色文本</span></span>
<span class="line"><span>console.log(&#39;\\x1b[41m\\x1b[37m红底白字\\x1b[0m&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 设置闪烁的黄色文本</span></span>
<span class="line"><span>console.log(&#39;\\x1b[33m\\x1b[5m闪烁的黄色文本\\x1b[0m&#39;);</span></span></code></pre></div><h4 id="光标控制" tabindex="-1">光标控制 <a class="header-anchor" href="#光标控制" aria-label="Permalink to &quot;光标控制&quot;">​</a></h4><p>除了控制输出文本，我们还可以控制光标位置，这些指令使用起来需要更多技巧性，但也赋予了我们更灵活地操作总控制台界面的能力。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/ae689806d3cd114776d2209997c97bf6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/ae689806d3cd114776d2209997c97bf6.png" alt=""></a></p><p>光标位置保存和恢复机制允许我们在终端中临时移动光标到其他位置，输出一些内容，然后返回到原来的位置继续输出。这种机制在以下场景特别有用：</p><ol><li>状态栏显示：在屏幕底部显示状态信息，同时保持主输出区域的光标位置。</li><li>进度显示：在固定位置更新进度，而不影响主输出流。</li><li>菜单系统：在特定位置显示菜单选项，同时保持其他内容不变。</li></ol><p>需要注意的是，终端只维护一个保存位置：</p><ul><li>每次保存操作会覆盖之前保存的位置。</li><li>恢复操作总是恢复到最近一次保存的位置。</li></ul><p>例如，我们可以实现一个简单的状态栏：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 保存当前光标位置</span></span>
<span class="line"><span>process.stdout.write(&#39;\\x1b[s&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 移动到屏幕底部</span></span>
<span class="line"><span>process.stdout.write(&#39;\\x1b[20;1H&#39;);</span></span>
<span class="line"><span>// 输出状态栏</span></span>
<span class="line"><span>process.stdout.write(&#39;\\x1b[44m\\x1b[37m状态栏：正在处理...\\x1b[0m&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 恢复到之前保存的位置</span></span>
<span class="line"><span>process.stdout.write(&#39;\\x1b[u&#39;);</span></span>
<span class="line"><span>// 继续在主输出区域输出</span></span>
<span class="line"><span>console.log(&#39;继续输出主内容&#39;);</span></span></code></pre></div><p>需要注意的是：</p><ol><li>保存和恢复操作是成对的，每次保存后应该对应一次恢复。</li><li>保存的位置会被新的保存操作覆盖。</li><li>某些终端可能对保存位置的数量有限制。</li></ol><p>光标控制指令的使用示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 获取光标位置</span></span>
<span class="line"><span>process.stdout.write(&#39;\\x1b[6n&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 监听标准输入以接收光标位置响应</span></span>
<span class="line"><span>process.stdin.once(&#39;data&#39;, (data) =&amp;gt; {</span></span>
<span class="line"><span>    // 解析返回的光标位置</span></span>
<span class="line"><span>    const match = data.toString().match(/\\[(\\d+);(\\d+)R/);</span></span>
<span class="line"><span>    if (match) {</span></span>
<span class="line"><span>        const [_, row, col] = match;</span></span>
<span class="line"><span>        console.log(\`当前光标位置：第 \${row} 行，第 \${col} 列\`);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>获取窗口大小的示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 获取窗口大小</span></span>
<span class="line"><span>process.stdout.write(&#39;\\x1b[18t&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 监听标准输入以接收窗口大小响应</span></span>
<span class="line"><span>process.stdin.once(&#39;data&#39;, (data) =&amp;gt; {</span></span>
<span class="line"><span>    // 解析返回的窗口大小</span></span>
<span class="line"><span>    const match = data.toString().match(/\\[8;(\\d+);(\\d+)t/);</span></span>
<span class="line"><span>    if (match) {</span></span>
<span class="line"><span>        const [_, height, width] = match;</span></span>
<span class="line"><span>        console.log(\`当前窗口大小：\${width} 列 × \${height} 行\`);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><h4 id="其他终端控制指令" tabindex="-1">其他终端控制指令 <a class="header-anchor" href="#其他终端控制指令" aria-label="Permalink to &quot;其他终端控制指令&quot;">​</a></h4><p>除了上面两组指令，还有一些其它指令，重要性没那么高，此处仅列出，需要用到时查询即可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/0c44cec4f1fbef6ced035a0c9f7be16f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/0c44cec4f1fbef6ced035a0c9f7be16f.png" alt=""></a></p><h4 id="表格边框字符" tabindex="-1">表格边框字符 <a class="header-anchor" href="#表格边框字符" aria-label="Permalink to &quot;表格边框字符&quot;">​</a></h4><p>有了在控制台中控制光标和文本能力，有时我们还希望有些线框来丰富视觉表现，这就要用到另一中机制：Unicode 表格字符。以下是常用的表格边框字符：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/fb54f95f4dd1c1cee3ef24271c063c30.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/fb54f95f4dd1c1cee3ef24271c063c30.png" alt=""></a></p><p>我们需要理解这些字符设计的内在逻辑，即以半角字符中心点，水平竖直四个方向都可以有不同形状的线，粗细、单双均可自由组合，但是粗线和双线不能自由组合。</p><p>因此我们利用这些字符绘制线条时，起点和终点总是字符中心点或者字符边缘，而交汇点总是字符中心点。</p><p>需要注意的是， <strong>不同终端对 Unicode 字符的支持可能不同，请一定要在目标终端上测试这些字符的可用性。</strong></p><h4 id="填充字符" tabindex="-1">填充字符 <a class="header-anchor" href="#填充字符" aria-label="Permalink to &quot;填充字符&quot;">​</a></h4><p>在终端中，我们可以使用不同密度的 Unicode 字符来创建填充效果。以下是常用的填充字符：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/43fbd65cd7d427de2f99658ebe89d2b7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/43fbd65cd7d427de2f99658ebe89d2b7.png" alt=""></a></p><h4 id="emoji-字符" tabindex="-1">Emoji 字符 <a class="header-anchor" href="#emoji-字符" aria-label="Permalink to &quot;Emoji 字符&quot;">​</a></h4><p>在终端中，我们可以使用 emoji 来增加界面的趣味性和可读性。Emoji 是一种特殊的 Unicode 字符，它们具有以下特点：</p><ul><li>组合机制：基础 emoji 由单个 Unicode 码点组成。</li><li>复杂 emoji 由多个 Unicode 码点组合而成。</li><li>可以使用变体选择符（VS）来改变 emoji 的样式。</li><li>可以使用零宽连接符（ZWJ）来组合多个 emoji。</li></ul><p>示例 1：</p><ul><li>基础 emoji：😊（笑脸）</li><li>复杂 emoji：👨‍👩‍👧‍👦（家庭）</li><li>变体选择符：☺️（笑脸）</li><li>零宽连接符组合：👨‍💻（程序员）</li><li>修饰符肤色修饰符：用于改变人物 emoji 的肤色</li><li>性别修饰符：用于改变人物 emoji 的性别</li><li>发型修饰符：用于改变人物 emoji 的发型</li><li>职业修饰符：用于改变人物 emoji 的职业</li></ul><p>示例 2：</p><ul><li>肤色修饰符： 👨🏻（浅肤色男性） 👨🏼（中浅肤色男性） 👨🏽（中肤色男性） 👨🏾（中深肤色男性） 👨🏿（深肤色男性）</li><li>性别修饰符： 👨（男性） 👩（女性）</li><li>职业修饰符： 👨‍💻（程序员） 👨‍🔬（科学家） 👨‍🏫（教师）</li><li>渲染机制不同平台可能使用不同的 emoji 字体</li><li>同一个 emoji 在不同平台上可能有不同的显示效果</li><li>某些平台可能不支持某些 emoji 的修饰符</li><li>emoji 的显示效果可能受到系统字体设置的影响</li></ul><p>示例 3：</p><ul><li>同一 emoji 在不同平台上的显示差异： 👨‍💻（程序员） 👨‍💻（程序员，可能显示为 👨 💻）</li><li>修饰符支持差异： 👨‍👩‍👧‍👦（家庭，可能显示为 👨 👩 👧 👦）</li><li>编码特点大多数 emoji 使用 Unicode 扩展 B 及以后的编码空间</li><li>某些 emoji 可能需要多个 Unicode 码点来表示</li><li>emoji 的编码可能包含不可见的控制字符</li><li>某些 emoji 的编码可能因平台而异</li></ul><p>示例 4：</p><ul><li>单码点 emoji：😊（U+1F60A）</li><li>多码点 emoji：👨‍💻（U+1F468 U+200D U+1F4BB）</li><li>带修饰符 emoji：👨🏻（U+1F468 U+1F3FB）</li><li>复杂组合 emoji：👨‍👩‍👧‍👦（U+1F468 U+200D U+1F469 U+200D U+1F467 U+200D U+1F466）</li></ul><p>以下是开发者工具中常用的 emoji 分类：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/7ba085de0907a429dae7fcc1b402694e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%87%8D%E5%AD%A6%E5%89%8D%E7%AB%AF/images/868745/7ba085de0907a429dae7fcc1b402694e.png" alt=""></a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在 Node.js 工具开发中，控制台是一个功能强大的界面工具。通过合理使用各种控制台特性，我们可以实现丰富的命令行交互体验。</p><p>从基础的问答式 IO 到实时按键响应，从文本样式控制到光标位置管理，从表格边框绘制到进度条显示，从 emoji 表情到状态图标，控制台提供了全方位的界面控制能力。</p><p>这些特性不仅能够提升命令行工具的专业性和美观度，还能增强用户体验和可用性。通过合理组合这些特性，我们可以开发出功能强大、界面友好的命令行工具。</p>`,78)])])}const g=a(i,[["render",l]]);export{b as __pageData,g as default};
